mapper.select:
SELECT CI.EMBRYO_CODE, CI.FIT_DRUM_PERIMETER, CI.ARTICLE_CROWN_SPEC, CI.BELT_CUTTING_ANGLE, CI.BELT_CODE1, CI.BELT_CRAFT1, CI.BELT_CODE2, CI.BELT_CRAFT2 FROM T_PRODUCT_CONSTRUCTION_INFO CI WHERE CI.DEL_FLAG = '0'
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
AND EXISTS (SELECT 1 FROM T_CX_SCHEDULE_RESULT R WHERE R.schedule_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION)

WITH temp_tab_BIG_ROLL_CODE AS (
SELECT #{bigRollCode} big_roll_code FROM dual
) SELECT ARTICLE_CROWN_SPEC BIG_ROLL_CODE, CEILING(SUM(IFNULL(R.SINGLE_SHIFT_LH_QTY, 0) * 3 * IFNULL(CI.FIT_DRUM_PERIMETER, 0) / 1000 * (IFNULL(CI.BELT_CRAFT1, 0) + IFNULL(CI.BELT_CRAFT2, 0)) / 1000) / #{breadth}) DAY_USED /*通过成型的单班硫化量计算，每天3个班；施工表的参数计量单位需要换算成“米”，向上取整*/ FROM T_CX_SCHEDULE_RESULT R INNER JOIN t_cx_auto_schedule_record sr ON sr.CX_BATCH_NO = R.CX_BATCH_NO AND sr.DEL_FLAG = '0' LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON CI.EMBRYO_CODE = R.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0'
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
AND ARTICLE_CROWN_SPEC IN ( SELECT big_roll_code FROM temp_tab_BIG_ROLL_CODE ) GROUP BY ARTICLE_CROWN_SPEC


SELECT N.BIG_ROLL_CODE, N.NOTES
  FROM T_GDYY_NOTE N
 WHERE DEL_FLAG = '0'
   AND N.STATUS = '0'
   AND N.START_TIME <= #{scheduleDate}
   AND N.END_TIME >= #{scheduleDate}

mapper.update:
    UPDATE T_GDYY_AUTO_SCHEDULE_RECORD
    SET DEL_FLAG  = '1',
        UPDATE_BY = #{createBy},
	       UPDATE_TIME = #{createTime}
	 WHERE schedule_date = #{scheduleDate}
	   AND DEL_FLAG = '0'

mapper.select:
WITH temp_tab_BIG_ROLL_CODE AS (
SELECT #{schedule.bigRollCode} big_roll_code FROM dual
) SELECT CI.ARTICLE_CROWN_SPEC bigRollCode, MAX(R.CX_BATCH_NO) CX_BATCH_NO FROM T_PRODUCT_CONSTRUCTION_INFO CI LEFT JOIN T_CX_SCHEDULE_RESULT R ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION AND R.DEL_FLAG = '0' AND R.SCHEDULE_DATE = #{scheduleDate} WHERE CI.DEL_FLAG = '0' AND CI.ARTICLE_CROWN_SPEC IN ( SELECT big_roll_code FROM temp_tab_BIG_ROLL_CODE ) GROUP BY CI.ARTICLE_CROWN_SPEC

SELECT *
  FROM T_GDYY_SCHEDULE_RESULT t
 WHERE t.SCHEDULE_DATE = #{scheduleDate}

SELECT * FROM t_gdyy_machine_info WHERE del_flag = '0'

	AND ID IN

		#{id}

mapper.update:
UPDATE T_GDYY_SCHEDULE_RESULT as a JOIN (
SELECT #{item.id} AS id, #{item.batchNo} as batch_no, #{item.orderNo} as order_no FROM DUAL
) tempTable ON a.id = tempTable.id SET a.batch_no = tempTable.batch_no, a.order_no = tempTable.order_no where a.del_flag = '0'
